const MAX = 200;
const FORBIDDEN = ["\n", "\r", "\u2028", "\u2029", "\u0000", "\uFEFF"];

export function validateEntry(bytes) {
  const errors = [];

  if (bytes.length === 0) {
    errors.push("empty file");
    return { ok: false, errors, length: 0 };
  }

  let text;
  try {
    text = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch (err) {
